package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class CourseProgressApiTest {
 CourseProgressStore store;CourseContextClient client;CourseProgressController api;CourseContextClient.Reference ref;UUID group,course,study,actor;String token="a".repeat(43);
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());actor=ids.next();group=ids.next();course=ids.next();study=ids.next();ref=new CourseContextClient.Reference(actor,group,ids.next(),course,3,"ACTIVE","MEMBER",ids.next(),1,"ENROLLED",List.of(new CourseContextClient.Study(study,1,"Study")));store=mock(CourseProgressStore.class);client=mock(CourseContextClient.class);var body=new RoadmapController(mock(RoadmapStore.class),mock(SpaceAuthorizationClient.class),new SimpleMeterRegistry(),"https://localhost:8443");api=new CourseProgressController(store,client,body,new SimpleMeterRegistry(),"https://localhost:8443");when(client.check(eq(group),eq(course),eq(token),anyString())).thenReturn(ref);}
 MockHttpServletRequest req(String method,String body){var r=new MockHttpServletRequest(method,"/");r.setSecure(true);r.addHeader("Cookie","__Host-brain_guest="+token);r.addHeader("Origin","https://localhost:8443");r.addHeader("If-Match","\"cp0\"");r.setContentType("application/json");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 String input(){return "{\"status\":\"COMPLETED\",\"courseVersion\":3,\"enrollmentVersion\":1}";}
 CourseProgressStore.Progress value(){return new CourseProgressStore.Progress(study,group,ref.spaceId(),course,actor,1,3,ref.enrollmentId(),1,"PRIVATE","PARTICIPANT_ONLY",List.of(new CourseProgressStore.Step(study,"COMPLETED")),Instant.now().toString());}
 @Test void authenticatedReferenceSuppliesActorAndSourceIdsForWrite()throws Exception{when(store.change(eq(ref),eq(study),eq(0L),eq("COMPLETED"),anyString())).thenReturn(value());var v=api.change(group.toString(),course.toString(),study.toString(),req("PUT",input()));assertEquals("\"cp1\"",v.getHeaders().getETag());assertEquals("no-store",v.getHeaders().getCacheControl());verify(store).change(eq(ref),eq(study),eq(0L),eq("COMPLETED"),anyString());}
 @Test void viewerWithdrawnAndRetiredContextsCanReadButNeverWrite(){for(var denied:List.of(new CourseContextClient.Reference(actor,group,ref.spaceId(),course,3,"ACTIVE","VIEWER",ref.enrollmentId(),1,"ENROLLED",ref.studies()),new CourseContextClient.Reference(actor,group,ref.spaceId(),course,3,"ACTIVE","MEMBER",ref.enrollmentId(),2,"WITHDRAWN",ref.studies()),new CourseContextClient.Reference(actor,group,ref.spaceId(),course,4,"RETIRED","MEMBER",ref.enrollmentId(),1,"ENROLLED",ref.studies()))){when(client.check(any(),any(),any(),any())).thenReturn(denied);assertEquals(409,assertThrows(ResponseStatusException.class,()->api.change(group.toString(),course.toString(),study.toString(),req("PUT",input()))).getStatusCode().value());}verifyNoInteractions(store);}
 @Test void changedContextAndStrictBodiesFailBeforeLocalWrites(){for(String body:List.of(input().replace("Version\":3","Version\":2"),input().replace("Version\":1","Version\":2"),input().replace("}",",\"participantId\":\"spoof\"}"),input()+" {}",input().replace("\"status\":","\"status\":\"IN_PROGRESS\",\"status\":")))assertThrows(ResponseStatusException.class,()->api.change(group.toString(),course.toString(),study.toString(),req("PUT",body)));var missing=req("PUT",input());missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.change(group.toString(),course.toString(),study.toString(),missing)).getStatusCode().value());verifyNoInteractions(store);}
 @Test void insecureDuplicateCookieAndCrossOriginDoNotCallAuthority(){var a=req("PUT",input());a.setSecure(false);var b=req("PUT",input());b.addHeader("Cookie","__Host-brain_guest="+token);var c=req("PUT",input());c.addHeader("Origin","https://evil.invalid");for(var v:List.of(a,b,c))assertThrows(ResponseStatusException.class,()->api.change(group.toString(),course.toString(),study.toString(),v));verifyNoInteractions(store,client);}
 @Test void deniedOrUnavailableAuthorityStopsLocalReadsAndWrites(){when(client.check(any(),any(),any(),any())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE));assertThrows(ResponseStatusException.class,()->api.get(group.toString(),course.toString(),req("GET",null)));assertThrows(ResponseStatusException.class,()->api.change(group.toString(),course.toString(),study.toString(),req("PUT",input())));var q=req("GET",null);q.addParameter("participantId",actor.toString());assertThrows(ResponseStatusException.class,()->api.get(group.toString(),course.toString(),q));var history=req("GET",null);history.addParameter("limit","11");assertThrows(ResponseStatusException.class,()->api.history(group.toString(),course.toString(),history));verifyNoInteractions(store);}
}
